@push('scripts')<script>
$(function(){
 const canCreate=@json(auth()->user()->can('packing.create')),canUpdate=@json(auth()->user()->can('packing.update')),canManage=canCreate||canUpdate,modalEl=document.getElementById('packingModal'),modal=modalEl?new bootstrap.Modal(modalEl):null,moModal=canManage?new bootstrap.Modal(document.getElementById('packingMoModal')):null,materialModal=canManage?new bootstrap.Modal(document.getElementById('packingMaterialModal')):null;
 const table=$('#packingTable').DataTable({processing:true,serverSide:true,responsive:true,ajax:{url:@json(route('super.packing.dt')),data:d=>{d.from_date=$('#packingFrom').val();d.to_date=$('#packingTo').val()}},columns:[{data:'DT_RowIndex',orderable:false,searchable:false},{data:'actions',orderable:false,searchable:false,className:'text-nowrap'},{data:'number',name:'packing_number'},{data:'date',name:'processed_at',render:d=>d?new Date(d+'T00:00:00').toLocaleDateString():''},{data:'planning',name:'productionOrder.no_cbd'}],order:[[3,'desc']],drawCallback:()=>window.feather&&feather.replace()});
 const safe=v=>$('<div>').text(v??'—').html();
 function detailMarkup(d){return `<div class="p-3 bg-light-subtle"><div class="table-responsive"><table class="table table-sm table-bordered bg-white mb-0"><thead><tr><th>{{ __('ui.packing.style') }}</th><th>{{ __('ui.packing.product_code') }}</th><th>{{ __('ui.packing.product_name') }}</th><th>{{ __('ui.packing.sewing_reception') }}</th><th>{{ __('ui.packing.quantity') }}</th><th>{{ __('ui.packing.rejected') }}</th><th>{{ __('ui.packing.send_to_finished_goods') }}</th><th>{{ __('ui.packing.po_buyer') }}</th><th>{{ __('ui.packing.mo') }}</th><th>{{ __('ui.packing.material_code') }}</th><th>{{ __('ui.packing.material_name') }}</th><th>{{ __('ui.packing.material_unit') }}</th><th>{{ __('ui.packing.material_waste') }}</th></tr></thead><tbody><tr><td>${safe(d.style)}</td><td>${safe(d.product_code)}</td><td>${safe(d.product_name)}</td><td class="text-end">${safe(d.sewing_reception)}</td><td class="text-end">${safe(d.input_quantity)}</td><td class="text-end">${safe(d.rejected_quantity)}</td><td class="text-end">${safe(d.good_quantity)}</td><td>${safe(d.po_buyer)}</td><td>${safe(d.mo)}</td><td>${safe(d.material_code)}</td><td>${safe(d.material_name)}</td><td>${safe(d.material_unit)}</td><td class="text-end">${safe(d.material_waste_quantity)}</td></tr></tbody></table></div></div>`}
 $('#packingTable').on('click','.btn-show-packing-detail',function(){const tr=$(this).closest('tr'),row=table.row(tr);if(row.child.isShown()){row.child.hide();tr.removeClass('shown');$(this).text(@json(__('ui.common.view_detail')))}else{row.child(detailMarkup(row.data())).show();tr.addClass('shown');$(this).text(@json(__('ui.common.close')))}});
 if(canManage){
  const moTable=canCreate?$('#packingMoTable').DataTable({processing:true,serverSide:true,responsive:true,ajax:@json(route('super.packing.production-orders.dt')),columns:[{data:'number',name:'number'},{data:'buyer_po_number',name:'buyer_po_number'},{data:'style',orderable:false,searchable:false},{data:'product_code',orderable:false,searchable:false},{data:'product_name',orderable:false,searchable:false},{data:'available_sewing_quantity',className:'text-end'},{data:'actions',orderable:false,searchable:false}]}):null;
  const materialTable=$('#packingMaterialTable').DataTable({processing:true,serverSide:true,responsive:true,ajax:{url:@json(route('super.packing.materials.dt')),data:d=>d.production_order_id=$('#packingMoId').val()},columns:[{data:'code'},{data:'name'},{data:'unit',orderable:false,searchable:false},{data:'actions',orderable:false,searchable:false}]});
  const reset=()=>{$('#packingForm')[0].reset();$('#packingEntryId,#packingMoId,#packingMaterialId').val('');$('#packingDate').val(@json(now()->toDateString()));$('#packingNumber,#packingMoLabel,#packingProduct,#packingStyle,#packingUnit,#packingPoBuyer,#packingAvailable,#packingMaterialLabel,#packingMaterialUnit').val('');$('#packingReject,#packingFinished,#packingWaste').val(0);$('#savePacking').html('<i data-feather="save" class="icon-sm me-1"></i>'+@json(__('ui.common.save')));if(canCreate)$.get(@json(route('super.packing.number-preview'))).done(r=>$('#packingNumber').val(r.number))};
  if(canCreate){$('#addPacking').on('click',()=>{reset();modal.show()});$('#choosePackingMo').on('click',()=>{modal.hide();moTable.ajax.reload();moModal.show()})}
  if(canCreate)$(document).on('click','.btn-select-packing-mo',function(){const b=$(this);$('#packingMoId').val(b.data('id'));$('#packingMoLabel').val(b.data('number'));$('#packingProduct').val(b.data('product'));$('#packingStyle').val(b.data('style'));$('#packingPoBuyer').val(b.data('po'));$('#packingUnit').val(b.data('unit'));$('#packingAvailable').val(b.data('available'));$('#packingQty').attr('max',b.data('available'));moModal.hide();modal.show();materialTable.ajax.reload()});
  $('#choosePackingMaterial').on('click',()=>{if(!$('#packingMoId').val())return;modal.hide();materialTable.ajax.reload();materialModal.show()});$(document).on('click','.btn-select-packing-material',function(){const b=$(this);$('#packingMaterialId').val(b.data('id'));$('#packingMaterialLabel').val(b.data('label'));$('#packingMaterialUnit').val(b.data('unit'));materialModal.hide();modal.show()});
  $('#packingForm').on('submit',function(e){e.preventDefault();const id=$('#packingEntryId').val(),url=id?@json(route('super.packing.update',['entry'=>'__ID__'])).replace('__ID__',id):@json(route('super.packing.store'));$.ajax({url,method:id?'PUT':'POST',data:$(this).serialize()}).done(r=>{modal.hide();table.ajax.reload(null,false);Swal.fire({icon:'success',title:@json(__('ui.workflow.success')),text:r.message})}).fail(x=>Swal.fire({icon:'error',title:@json(__('ui.workflow.failure')),text:Object.values(x.responseJSON?.errors||{}).flat().join('\n')||x.responseJSON?.message||'Error'}))});
  $(document).on('click','.btn-edit-packing',function(){const b=$(this);reset();$('#packingEntryId').val(b.data('id'));$('#packingMoId').val(b.data('mo'));$('#packingMoLabel').val(b.data('mo-number'));$('#packingProduct').val(b.data('product'));$('#packingStyle').val(b.data('style'));$('#packingPoBuyer').val(b.data('po'));$('#packingUnit').val(b.data('unit'));$('#packingDate').val(b.data('date'));$('#packingQty').val(b.data('input'));$('#packingFinished').val(b.data('good'));$('#packingReject').val(b.data('reject'));$('#packingMaterialId').val(b.data('material'));$('#packingMaterialLabel').val(b.data('material-label'));$('#packingMaterialUnit').val(b.data('material-unit'));$('#packingWaste').val(b.data('waste'));$('#packingNumber').val(b.data('number'));$('#packingAvailable').val(b.data('available'));$('#packingQty').attr('max',b.data('available'));$('#savePacking').text(@json(__('ui.common.save_changes')));modal.show()});
 }
 $(document).on('click','.btn-delete-packing',function(){const id=$(this).data('id');Swal.fire({icon:'warning',title:@json(__('ui.common.confirm_delete')),showCancelButton:true,confirmButtonText:@json(__('ui.common.delete')),cancelButtonText:@json(__('ui.common.cancel'))}).then(x=>{if(x.isConfirmed)$.ajax({url:@json(route('super.packing.destroy',['entry'=>'__ID__'])).replace('__ID__',id),method:'DELETE',data:{_token:@json(csrf_token())}}).done(r=>{table.ajax.reload(null,false);Swal.fire({icon:'success',text:r.message})}).fail(x=>Swal.fire({icon:'error',text:Object.values(x.responseJSON?.errors||{}).flat().join('\n')||x.responseJSON?.message||'Error'}))})});
 $('#packingFilter').on('click',()=>table.ajax.reload());$('#packingExport').on('click',function(e){e.preventDefault();const q=new URLSearchParams();if($('#packingFrom').val())q.set('from_date',$('#packingFrom').val());if($('#packingTo').val())q.set('to_date',$('#packingTo').val());location.href=this.href+'?'+q.toString()});
});
</script>@endpush
